import java.util.*;

public class Main {
    static final int maxN = 70;
    static long[][] C = new long[maxN + 5][maxN + 5];
    static int n, m, N, mid;
    static int[] g = new int[maxN + 5];
    static List<PairSC>[][] partb;
    static Map<Long, Long>[][] parta;
    static long ans = Long.MAX_VALUE, ans_cnt = 0;

    static class PairSC {
        long sum;
        long cnt;
        PairSC(long sum, long cnt) {
            this.sum = sum;
            this.cnt = cnt;
        }
    }

    static void prepare() {
        for (int i = 0; i < maxN; ++i) {
            C[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        }
    }

    static void dfs_partb(int x, int cnta, int cntb, long sum) {
        if (x == mid) {
            partb[cnta][cntb].add(new PairSC(sum, 1));
            return;
        }
        for (int i = 0; i < 2; ++i) {
            if (g[x - 1] != -1 && i != g[x - 1]) continue;
            long tmp = 0;
            if (i == 0) {
                if (cnta > 0) {
                    for (int j = 0; j < n; ++j)
                        tmp += C[cnta - 1][n - 1] * C[cntb][j] * C[N - x][n - j];
                    dfs_partb(x - 1, cnta - 1, cntb, sum + tmp);
                }
            } else {
                if (cntb > 0) {
                    for (int j = 0; j < n; ++j)
                        tmp -= C[cntb - 1][n - 1] * C[cnta][j] * C[N - x][n - j];
                    dfs_partb(x - 1, cnta, cntb - 1, sum + tmp);
                }
            }
        }
    }

    static int findFirstGeq(List<PairSC> list, long target) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (list.get(mid).sum < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static void update(long val, long cnt) {
        if (val < ans) {
            ans = val;
            ans_cnt = cnt;
        } else if (val == ans) {
            ans_cnt += cnt;
        }
    }

    static void bfs_parta() {
        for (int i = 0; i <= n + m + 1; ++i)
            for (int j = 0; j <= n + m + 1; ++j)
                parta[i][j].clear();
        parta[0][0].put(0L, 1L);

        for (int i = 0; i <= n + m + 1; ++i) {
            for (int j = 0; j <= n + m + 1; ++j) {
                Map<Long, Long> map = parta[i][j];
                if (map.isEmpty()) continue;
                for (Map.Entry<Long, Long> u : map.entrySet()) {
                    if (i + j == mid) {
                        List<PairSC> list = partb[i][j];
                        if (list.isEmpty()) continue;
                        long target = -u.getKey();
                        int p = findFirstGeq(list, target);
                        if (p < list.size()) {
                            update(Math.abs(u.getKey() + list.get(p).sum), u.getValue() * list.get(p).cnt);
                        }
                        if (p > 0) {
                            update(Math.abs(u.getKey() + list.get(p - 1).sum), u.getValue() * list.get(p - 1).cnt);
                        }
                    } else {
                        int p = i + j;
                        for (int k = 0; k < 2; ++k) {
                            if (g[p] != -1 && k != g[p]) continue;
                            int cnta = i, cntb = j;
                            if (k == 0) cnta++;
                            else cntb++;
                            if (cnta <= n + m && cntb <= n + m) {
                                long tmp = 0;
                                if (k == 0) {
                                    for (int l = 0; l < n; ++l)
                                        tmp += C[cnta - 1][n - 1] * C[cntb][l] * C[N - p - 1][n - l];
                                } else {
                                    for (int l = 0; l < n; ++l)
                                        tmp -= C[cntb - 1][n - 1] * C[cnta][l] * C[N - p - 1][n - l];
                                }
                                long newSum = u.getKey() + tmp;
                                Map<Long, Long> dest = parta[cnta][cntb];
                                dest.put(newSum, dest.getOrDefault(newSum, 0L) + u.getValue());
                            }
                        }
                    }
                }
            }
        }
    }

    static void work() {
        for (int i = 0; i <= n + m + 1; ++i)
            for (int j = 0; j <= n + m + 1; ++j)
                partb[i][j].clear();
        dfs_partb(N, n + m, n + m, 0);
        for (int i = 0; i <= n + m + 1; ++i) {
            for (int j = 0; j <= n + m + 1; ++j) {
                List<PairSC> list = partb[i][j];
                if (list.isEmpty()) continue;
                Collections.sort(list, (a, b) -> Long.compare(a.sum, b.sum));
                List<PairSC> newList = new ArrayList<>();
                int idx = 0;
                while (idx < list.size()) {
                    long curSum = list.get(idx).sum;
                    long curCnt = 0;
                    while (idx < list.size() && list.get(idx).sum == curSum) {
                        curCnt += list.get(idx).cnt;
                        idx++;
                    }
                    newList.add(new PairSC(curSum, curCnt));
                }
                partb[i][j] = newList;
            }
        }
        bfs_parta();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        prepare();
        n = sc.nextInt();
        m = sc.nextInt();
        String s = sc.next();
        N = (n + m) << 1;
        mid = Math.max(0, N - 22);
        Arrays.fill(g, -1);

        // allocate partb and parta arrays of sufficient size
        int size = n + m + 2;
        partb = new List[size][size];
        parta = new Map[size][size];
        for (int i = 0; i < size; ++i) {
            for (int j = 0; j < size; ++j) {
                partb[i][j] = new ArrayList<>();
                parta[i][j] = new HashMap<>();
            }
        }

        work();
        ans_cnt = 0;
        for (int i = 0; i < N; ++i) {
            if (s.charAt(i) == 'A') g[i] = 0;
            else if (s.charAt(i) == 'B') g[i] = 1;
        }
        work();
        System.out.println(ans_cnt);
        sc.close();
    }
}
